<?php
namespace App\Entity;
use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity]
class VisiteMedicale { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne] private ?Candidat $candidat=null; #[ORM\Column(type:'datetime')] private ?\DateTimeInterface $dateHeure=null; #[ORM\Column(length:180)] private string $centre=''; #[ORM\Column(length:20)] private string $aptitude='EN_ATTENTE'; #[ORM\Column(length:255,nullable:true)] private ?string $certificat=null; #[ORM\Column(length:255,nullable:true)] private ?string $photo=null; #[ORM\Column(type:'text',nullable:true)] private ?string $observations=null; #[ORM\Column(name:'observationsPlanification',type:'text',nullable:true)] private ?string $observationsPlanification=null; public function getId():?int{return $this->id;} public function getCandidat():?Candidat{return $this->candidat;} public function setCandidat(?Candidat $v):self{$this->candidat=$v;return $this;} public function getDateHeure():?\DateTimeInterface{return $this->dateHeure;} public function setDateHeure(?\DateTimeInterface $v):self{$this->dateHeure=$v;return $this;} public function getCentre():string{return $this->centre;} public function setCentre(string $v):self{$this->centre=$v;return $this;} public function getAptitude():string{return $this->aptitude;} public function setAptitude(string $v):self{$this->aptitude=$v;return $this;} public function setCertificat(?string $v):self{$this->certificat=$v;return $this;} public function getCertificat():?string{return $this->certificat;} public function setPhoto(?string $v):self{$this->photo=$v;return $this;} public function getPhoto():?string{return $this->photo;} public function setObservations(?string $v):self{$this->observations=$v;return $this;} public function getObservations():?string{return $this->observations;} public function setObservationsPlanification(?string $v):self{$this->observationsPlanification=$v;return $this;} public function getObservationsPlanification():?string{return $this->observationsPlanification;} }
